def transform(grid):
    """Shift the non-background pattern down one row, as in the demonstrated pair."""
    if not grid or not grid[0]:
        return grid
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
    return out
